        <label class="num-field">Seat 1 is ${Xe("seat_one",[["pitch_left","Left, seen from the pitch"],["pitch_right","Right, seen from the pitch"],["guide_start","At the start of the guide"],["guide_end","At the end of the guide"]])}</label>
